new:
/// Returns the transient 2D/3D Scene View presentation mode.
pub fn dimension(&self) -> SceneViewDimension {
    self.dimension
}

/// Switches the Scene View presentation without mutating authored scene content.
pub fn set_dimension(&mut self, dimension: SceneViewDimension) {
    self.dimension = dimension;
}

/// Restores the active Scene View camera independently from authored cameras.
pub fn reset_camera(&mut self) {
    match self.dimension {
        SceneViewDimension::ThreeD => self.camera.reset(),
        SceneViewDimension::TwoD => self.camera_2d.reset(),
    }
}
